<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserWebauthnCredential\Domain\ValueObject\Accessor\UserWebauthnCredentialAuthenticatorAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserWebauthnCredentialAuthenticatorAccessor trait.
 *
 * Covers null default, string/VO assignment via withAuthenticator,
 * getAuthenticator/authenticator accessors, and isAuthenticatorChanged with/without original.
 */
class UserWebauthnCredentialAuthenticatorAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAuthenticator creates a new instance with the Authenticator set
     * from a string value, and getAuthenticator returns the primitive string.
     */
    public function testWithAuthenticatorFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialAuthenticatorAccessorUnitTest();

        // Act
        $result = $holder->withAuthenticator('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getAuthenticator());
    }
    /**
     * Asserts that withauthenticator has access to the value object
     * from a string value, and getAuthenticator returns the primitive string.
     */
    public function testWithAuthenticatorFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialAuthenticatorAccessorUnitTest();

        // Act
        $result = $holder->withAuthenticator('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->authenticator()->value());
    }
    public function testChangedAuthenticator(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialAuthenticatorAccessorUnitTest()->withAuthenticator('one');
        $original = $holder->withAuthenticator('one');
        $same = $holder->withAuthenticator('one');
        $modified = $holder->withAuthenticator('other');

        // Act
        $withSame = $original->isAuthenticatorChanged($same);
        $withDiferent = $original->isAuthenticatorChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserWebauthnCredentialAuthenticatorAccessorUnitTest
{
    use UserWebauthnCredentialAuthenticatorAccessor;
}
